steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -d '{
    "query": "{
      issue(identifier: \"WEB-5\") {
        id
        identifier
        title
        state {
          name
        }
        comments(first: 50) {
          nodes {
            id
            body
            user {
              name
            }
            createdAt
          }
        }
      }
    }
  }'
